import datetime


def validate_task(title, description, priority, due_date):
    errors = []
    if not title or len(title.strip()) == 0:
        errors.append('Title is required')
    if description and len(description) > 500:
        errors.append('Description too long')
    if priority not in ('low', 'medium', 'high', 'critical'):
        errors.append('Invalid priority')
    if isinstance(due_date, str):
        try:
            due_date = datetime.datetime.strptime(due_date, '%Y-%m-%d').date()
        except ValueError:
            errors.append('Invalid due_date format')
    if isinstance(due_date, datetime.date):
        if due_date < datetime.date.today():
            errors.append('Due date must be in the future')
    return errors

import datetime


class TaskStore:
    def __init__(self, tasks=None):
        self.tasks = tasks if tasks is not None else []
        self._next_id = 1

    def add(self, task):
        task['id'] = self._next_id
        self._next_id += 1
        self.tasks.append(task)
        return task

    def get(self, task_id):
        for t in self.tasks:
            if t['id'] == task_id:
                return t
        return None

    def list_by_priority(self):
        order = {'critical': 4, 'high': 3, 'medium': 2, 'low': 1}
        return sorted(self.tasks, key=lambda t: order.get(t['priority'], 0), reverse=True)

    def overdue(self):
        today = datetime.date.today()
        result = []
        for t in self.tasks:
            if t.get('due_date') and t['due_date'] < today:
                result.append(t)
        return result

    def complete(self, task_id):
        task = self.get(task_id)
        if task is None:
            raise ValueError('Task not found')
        task['completed'] = True
        task['completed_at'] = datetime.datetime.now()
        return task

    def summary(self):
        counts = {}
        for t in self.tasks:
            p = t['priority']
            counts[p] = counts.get(p, 0) + 1
        return counts

