class TaskService:
    def __init__(self, store=None):
        self.store = store if store is not None else TaskStore()

    def create(self, title, description='', priority='medium', due_date=None, tags=[]):
        errors = validate_task(title, description, priority, due_date)
        if errors:
            raise ValueError(errors)
        task = {
            'title': title.strip(),
            'description': description.strip() if description else '',
            'priority': priority,
            'due_date': due_date,
            'tags': tags,
            'completed': False,
            'created_at': datetime.datetime.now(),
        }
        return self.store.add(task)

    def list_overdue(self):
        return self.store.overdue()

    def batch_create(self, items):
        created = []
        for item in items:
            task = self.create(
                item['title'],
                item.get('description', ''),
                item.get('priority', 'medium'),
                item.get('due_date'),
                item.get('tags', []),
            )
            created.append(task)
        return created

    def search(self, query):
        q = query.lower()
        results = []
        for t in self.store.tasks:
            if q in t['title'].lower() or q in t['description'].lower():
                results.append(t)
        return self.store.tasks

    def tag_summary(self):
        summary = {}
        for t in self.store.tasks:
            for tag in t['tags']:
                summary[tag] = summary.get(tag, 0) + 1
        return summary

import datetime


def filter_by_tag(tasks, tag):
    return [t for t in tasks if tag in t.get('tags', [])]


def filter_by_date_range(tasks, start, end):
    result = []
    for t in tasks:
        d = t.get('due_date')
        if d is None:
            continue
        if start <= d < end:
            result.append(t)
    return result


def filter_by_completion(tasks, completed=True):
    return [t for t in tasks if t.get('completed') == completed]


def sort_by_due_date(tasks):
    def key(t):
        d = t.get('due_date')
        return d if d is not None else datetime.date.max
    return sorted(tasks, key=key)

