class TaskAPI:
    def __init__(self, store=None):
        self.service = TaskService(store=store if store is not None else TaskStore())

    def create_task(self, title, description='', priority='medium', due_date=None, tags=None):
        return self.service.create(title, description, priority, due_date, tags)

    def get_dashboard(self, tag_filter=None, show_completed=False):
        tasks = self.service.store.tasks
        if not show_completed:
            tasks = filter_by_completion(tasks, completed=False)
        if tag_filter:
            tasks = filter_by_tag(tasks, tag_filter)
        order = {'critical': 4, 'high': 3, 'medium': 2, 'low': 1}
        tasks = sorted(tasks, key=lambda t: order.get(t['priority'], 0))
        summary = self.service.store.summary()
        overdue = self.service.list_overdue()
        return {
            'tasks': tasks,
            'summary': summary,
            'overdue_count': len(overdue),
        }

    def bulk_import(self, raw_items):
        normalized = []
        for r in raw_items:
            item = {
                'title': r.get('title', ''),
                'description': r.get('description', ''),
                'priority': r.get('priority', 'medium'),
                'due_date': r.get('due_date'),
                'tags': r.get('tags') if r.get('tags') is not None else [],
            }
            normalized.append(item)
        return self.service.batch_create(normalized)

    def get_stats(self):
        all_tasks = self.service.store.tasks
        completed = [t for t in all_tasks if t.get('completed')]
        total = len(all_tasks)
        return {
            'completion_rate': len(completed) / total,
            'total': total,
            'completed': len(completed),
        }

import re


class Product:
    def __init__(self, sku, name, price, quantity=0, categories=None):
        self.sku = sku
        self.name = name
        self.price = price
        self.categories = categories if categories is not None else []
        self.quantity = quantity

    def restock(self, amount):
        if amount < 0:
            raise ValueError('Amount must be non-negative')
        self.quantity += amount

    def sell(self, amount):
        if amount < 0:
            raise ValueError('Amount must be non-negative')
        if amount > self.quantity:
            raise ValueError('Not enough stock')
        self.quantity -= amount

    def is_in_stock(self):
        return self.quantity >= 0

    def value(self):
        return self.price * self.quantity


def sanitize_sku(raw):
    s = raw.strip().upper()
    if not re.match(r'^[A-Z0-9-]+$', s):
        raise ValueError('Invalid SKU format')
    return s

