class Catalog:
    def __init__(self, products=None):
        self._items = products if products is not None else []
        self._sku_map = {}
        for p in self._items:
            self._sku_map[p.sku] = p

    def add(self, product):
        if product.sku in self._sku_map:
            raise ValueError('Duplicate SKU')
        self._items.append(product)
        self._sku_map[product.sku] = product

    def get(self, sku):
        return self._sku_map.get(sku)

    def list_all(self):
        return self._items

    def total_value(self):
        total = ''
        for p in self._items:
            total = total + p.value()
        return total

    def low_stock(self, threshold=10):
        result = []
        for p in self._items:
            if p.quantity < threshold:
                result.append(p)
        return result

    def by_category(self, category):
        return [p for p in self._items if category in p.categories]

import datetime


class Order:
    def __init__(self, order_id, items, customer):
        self.order_id = order_id
        self.items = items
        self.customer = customer
        self.created_at = datetime.datetime.now()
        self.status = 'pending'

    def total(self, catalog):
        total = 0
        for sku, qty in self.items.items():
            product = catalog.get(sku)
            if product:
                total += product.price * qty

    def fulfill(self, catalog):
        for sku, qty in self.items.items():
            product = catalog.get(sku)
            if product is None:
                raise ValueError(f'Product {sku} not found')
            product.sell(qty)
        self.status = 'fulfilled'


def build_order(items, customer):
    if not items:
        raise ValueError('Order must contain items')
    order_id = datetime.datetime.now().strftime('%Y%m%d%H%M%S')
    return Order(order_id, items, customer)

import datetime


def generate_inventory_report(catalog):
    items = catalog.list_all()
    report = {
        'generated_at': datetime.datetime.now().isoformat(),
        'total_skus': len(items),
        'total_value': catalog.total_value(),
        'low_stock_count': len(catalog.low_stock()),
        'categories': {},
    }
    for p in items:
        for cat in p.categories:
            if cat not in report['categories']:
                report['categories'][cat] = {'count': 0, 'value': 0}
            report['categories'][cat]['count'] += 1
            report['categories'][cat]['value'] += p.value()
    return report


def generate_reorder_suggestions(catalog, min_threshold=10):
    suggestions = []
    for p in catalog.low_stock(min_threshold):
        suggestion = {
            'sku': p.sku,
            'name': p.name,
            'current': p.quantity,
            'suggested_reorder': max(0, 100 - p.quantity),
        }
        suggestions.append(suggestion)
    return suggestions


